//! TLS-wrapped proxy listener (issue #110).
//!
//! Acceptance tests for the credential-onboarding milestone's transport
//! security feature: when the listener TLS acceptor is attached, the
//! proxy port requires a TLS handshake before any proxy protocol —
//! CONNECT (and `Proxy-Authorization` with it) happens inside the TLS
//! tunnel, a plaintext CONNECT to the same port is refused without any
//! HTTP response, and the engine keeps its plaintext behavior
//! byte-identical when the option is unset.
//!
//! The listener certificate under test is a real leaf generated by the
//! engine's own `CertificateManager` for `localhost`, so the test client
//! performs FULL rustls verification (CA trust + server name) — no
//! verification bypasses.

use std::sync::Arc;
use std::time::Duration;

use async_trait::async_trait;
use madhyamas_core::tls::load_listener_tls_acceptor;
use madhyamas_core::{
    CertificateManager, ProxyAuthValidator, ProxyConfig, ProxyCredentials, ProxyEngine,
    ProxyPrincipal, TrafficStore, TrafficStoreBackend,
};
use madhyamas_test_utils::spawn_mock_server;
use parking_lot::RwLock;

/// Validator that rejects every supplied credential (strict-auth tests).
struct RejectingValidator;

#[async_trait]
impl ProxyAuthValidator for RejectingValidator {
    async fn validate(&self, _credentials: &ProxyCredentials) -> Result<ProxyPrincipal, String> {
        Err("test: all credentials rejected".to_string())
    }
}

/// Pick a free TCP port by binding to :0 and immediately releasing it.
fn free_port() -> u16 {
    std::net::TcpListener::bind("127.0.0.1:0")
        .expect("bind :0 for port discovery")
        .local_addr()
        .expect("local addr")
        .port()
}

/// Wait until the proxy listener accepts TCP connections. The probe
/// connection carries no TLS and closes immediately — the engine's TLS
/// acceptor fails it at debug level, which is the behavior under test
/// anyway.
async fn wait_for_listener(addr: &str) {
    for _ in 0..100 {
        if tokio::net::TcpStream::connect(addr).await.is_ok() {
            return;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    panic!("proxy listener at {addr} never came up");
}

/// Generate a real listener identity: a leaf certificate for `localhost`
/// signed by a fresh `CertificateManager` CA, written as PEM files.
/// Returns (cert_path, key_path, ca_pem) — the CA PEM lets test clients
/// verify the listener with full rustls validation.
async fn listener_identity(
    dir: &tempfile::TempDir,
) -> (std::path::PathBuf, std::path::PathBuf, Vec<u8>) {
    let cert_manager =
        CertificateManager::new(dir.path().join("ca.pem").to_str().expect("utf8 path"))
            .await
            .expect("certificate manager");
    let leaf = cert_manager
        .generate_cert_for_host("localhost")
        .expect("leaf for localhost");
    let cert_path = dir.path().join("listener-cert.pem");
    let key_path = dir.path().join("listener-key.pem");
    std::fs::write(&cert_path, &leaf.certificate).expect("write cert pem");
    std::fs::write(&key_path, &leaf.private_key).expect("write key pem");
    (
        cert_path,
        key_path,
        cert_manager.ca_certificate_pem().to_vec(),
    )
}

/// A rustls client config that trusts the test CA (full verification —
/// the listener cert carries SAN DNS:localhost).
fn client_config(ca_pem: &[u8]) -> Arc<rustls::ClientConfig> {
    let mut roots = rustls::RootCertStore::empty();
    let certs = rustls_pemfile::certs(&mut std::io::Cursor::new(ca_pem))
        .collect::<Result<Vec<_>, _>>()
        .expect("parse CA pem");
    assert!(!certs.is_empty(), "test CA pem must contain a certificate");
    for cert in certs {
        roots.add(cert).expect("trust test CA");
    }
    // Explicit provider: under cargo-nextest each test is its own process,
    // so this helper must not rely on another test's install_default().
    Arc::new(
        rustls::ClientConfig::builder_with_provider(Arc::new(
            rustls::crypto::ring::default_provider(),
        ))
        .with_safe_default_protocol_versions()
        .expect("ring provider")
        .with_root_certificates(roots)
        .with_no_client_auth(),
    )
}

/// Build a started engine on an ephemeral port. `acceptor` is attached
/// when `Some`, reproducing the binary's startup wiring.
async fn started_engine(
    acceptor: Option<Arc<tokio_rustls::TlsAcceptor>>,
    validator: Option<Arc<dyn ProxyAuthValidator>>,
) -> (String, Arc<TrafficStore>) {
    let _ = rustls::crypto::ring::default_provider().install_default();

    let store = TrafficStore::in_memory().await.expect("in-memory store");
    let cert_dir = tempfile::TempDir::new().expect("temp dir for MITM certs");
    let cert_manager =
        CertificateManager::new(cert_dir.path().join("ca.pem").to_str().expect("utf8 path"))
            .await
            .expect("certificate manager");

    let port = free_port();
    let proxy_addr = format!("127.0.0.1:{port}");
    let config = ProxyConfig {
        host: "127.0.0.1".to_string(),
        proxy_port: port,
        ..Default::default()
    };

    let mut engine = ProxyEngine::new(
        Arc::new(RwLock::new(config)),
        cert_manager,
        store.clone() as Arc<dyn TrafficStoreBackend + Send + Sync>,
    )
    .await
    .expect("engine");
    if let Some(acceptor) = acceptor {
        engine = engine.with_proxy_tls_acceptor(acceptor);
    }
    if let Some(validator) = validator {
        engine = engine.with_proxy_auth_validator(validator);
    }
    tokio::spawn(async move {
        let _ = engine.start().await;
    });
    wait_for_listener(&proxy_addr).await;
    (proxy_addr, store)
}

/// TLS-connect to the listener as a verified client and hand the session
/// to the caller.
async fn tls_connect(
    proxy_addr: &str,
    ca_pem: &[u8],
) -> tokio_rustls::client::TlsStream<tokio::net::TcpStream> {
    let tcp = tokio::net::TcpStream::connect(proxy_addr)
        .await
        .expect("tcp connect to proxy");
    let connector = tokio_rustls::TlsConnector::from(client_config(ca_pem));
    let server_name = rustls::pki_types::ServerName::try_from("localhost".to_string())
        .expect("server name localhost");
    connector
        .connect(server_name, tcp)
        .await
        .expect("TLS handshake with proxy listener")
}

/// Read from a stream until the HTTP header terminator (bounded — never
/// deadlock the test on a peer that stays silent).
async fn read_http_head<S: tokio::io::AsyncRead + Unpin>(stream: &mut S) -> Vec<u8> {
    let mut out = Vec::new();
    tokio::time::timeout(Duration::from_secs(5), async {
        use tokio::io::AsyncReadExt;
        let mut buf = [0u8; 512];
        loop {
            let n = stream.read(&mut buf).await.expect("read");
            if n == 0 {
                break;
            }
            out.extend_from_slice(&buf[..n]);
            if out.ends_with(b"\r\n\r\n") || out.starts_with(b"HTTP/1.1 407") {
                break;
            }
        }
    })
    .await
    .expect("bounded read");
    out
}

